// Verify installed module emits <openviking-hint>; emulate a real profile block.
import { buildProfileBlock } from "file:///C:/Users/Administrator/.dsh/profiles/web/node_modules/@openviking/dsh-memory-plugin/shared/profile-inject.mjs";
const fakeProfile = "# 当前用户\n- 身份：default as of 2026-11-14";
async function fetchJSON(path, init, opts) {
  if (path.includes("/content/read") || path.includes("profile.md")) return { ok: true, result: fakeProfile };
  if (path.includes("/fs/ls")) return { ok: true, result: [{ name: "profile.md", type: "file" }] };
  return { ok: true, result: "/user/default", space: "default" };
}
const res = await buildProfileBlock(fetchJSON, 800, "");
const has = !!res && res.block.includes("<openviking-hint>") && res.block.includes("mcp_gateway(server=openviking");
console.log("HINT_PRESENT=", has);
// also print the hint tail
if (res) { const i = res.block.indexOf("<openviking-hint>"); console.log("TAIL:", res.block.slice(i)); }

